#!/usr/bin/env bash
# Numerical parity tests. Both are optional:
#
#   TSFM_TEST_MODEL      -> a Chronos-2 directory
#   TSFM_TEST_TIMESTRAL  -> a Timestral directory (2-variate + covariate fixture)
#
# Each model is run twice, with one and eight threads, and compared against
# fixtures generated by the tsfm-zig CLI.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
psql="${PSQL:-psql}"
ran=0

run_parity() {
    local model="$1"
    local sql="$2"
    local label="$3"
    local threads

    for threads in 1 8; do
        echo "== ${label}, threads=${threads} =="
        "$psql" -X -q -U "${PGUSER:-postgres}" -d "${PGDATABASE:-postgres}" \
            -v ON_ERROR_STOP=1 \
            -v "model_dir=${model}" \
            -v "threads=${threads}" \
            -f "${root}/${sql}"
    done
}

if [[ -n "${TSFM_TEST_MODEL:-}" ]]; then
    run_parity "$TSFM_TEST_MODEL" "tests/parity.sql" "Chronos-2"
    ran=1
fi

if [[ -n "${TSFM_TEST_TIMESTRAL:-}" ]]; then
    run_parity "$TSFM_TEST_TIMESTRAL" "tests/timestral_parity.sql" "Timestral"
    ran=1
fi

if [[ "$ran" -eq 0 ]]; then
    echo "skip: set TSFM_TEST_MODEL and/or TSFM_TEST_TIMESTRAL to model directories"
fi
